/* clothesbuttons.h - the 77 first-level buttons of the clothes dialog.
 *
 * Generated by docs/v1.0.0/tools/gen_secondary_menus.py from
 * docs/clothes_add_widget_v3.md; do not edit by hand.
 *
 * `kind` is the document's own column: B a plain button, T a button that
 * also opens a menu and writes its own word, P a button that only opens a
 * menu. The menu of a T or P button is res/secondarymenu/clothes_<id>_menu.ui.
 */
#pragma once
#include <QString>
#include <QVector>

/// One first-level button: the word it writes and what kind of button it is.
struct clothesAddButton {
    const char* tag;
    char kind;
};

/// One body area of the dialog: its caption and its buttons in table order.
struct clothesAddArea {
    const char* heading;
    QVector<clothesAddButton> buttons;
};

/// The id a button's menu file is named after (SC-10).
inline QString clothesMenuId(const QString& tag)
{
    QString slug;
    for (const QChar c : tag) {
        if (c.isLetterOrNumber())
            slug += c.toLower();
        else if (!slug.isEmpty() && !slug.endsWith(QLatin1Char('_')))
            slug += QLatin1Char('_');
    }
    while (slug.endsWith(QLatin1Char('_')))
        slug.chop(1);
    return QStringLiteral("clothes_") + slug;
}

/// Where that button's menu lives.
inline QString clothesMenuPath(const QString& tag)
{
    return QStringLiteral(":/secondarymenu/") + clothesMenuId(tag)
           + QStringLiteral("_menu.ui");
}

